// src/views/SignupView.jsx
import React, { useState } from "react";
import { useAuthController } from "../controllers/AuthController";
import { Link, useNavigate } from "react-router-dom";
import { useAuth } from "../context/AuthContext";
import "../styles/main.css";
import "../styles/SignUp.css";


const SignupView = () => {
  const { signupWithEmail } = useAuthController();
  const { setIsGuest } = useAuth(); // Import guest mode setter
  const navigate = useNavigate();

  const [firstName, setFirstName] = useState("");
  const [lastName, setLastName] = useState("");
  const [phone, setPhone] = useState("");
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [confirmPwd, setConfirmPwd] = useState("");
  const [errorMsg, setErrorMsg] = useState("");

  const handleSignup = async (e) => {
    e.preventDefault();
    if (password !== confirmPwd) {
      setErrorMsg("Passwords do not match");
      return;
    }
    try {
      await signupWithEmail(email, password, { firstName, lastName, phone });
      navigate("/"); // Redirect to home after successful signup
    } catch (error) {
      setErrorMsg(error.message);
    }
  };

  const handleGuestLogin = () => {
    setIsGuest(true); // Enable guest mode
    navigate("/"); // Redirect to home as a guest
  };

  return (
    <div className="sign-container">
  <h2>Signup</h2>
  <form onSubmit={handleSignup} className="auth-form">
    <input type="text" placeholder="First Name" value={firstName} onChange={(e) => setFirstName(e.target.value)} required />
    <input type="text" placeholder="Last Name" value={lastName} onChange={(e) => setLastName(e.target.value)} required />
    <input type="tel" placeholder="Phone Number" value={phone} onChange={(e) => setPhone(e.target.value)} required />
    <input type="email" placeholder="Email Address" value={email} onChange={(e) => setEmail(e.target.value)} required />
    <input type="password" placeholder="Password" value={password} onChange={(e) => setPassword(e.target.value)} required />
    <input type="password" placeholder="Confirm Password" value={confirmPwd} onChange={(e) => setConfirmPwd(e.target.value)} required />

    <div className="auth-buttons"> 
      <button type="submit">Signup</button>
      <button onClick={handleGuestLogin} className="guest-btn">Continue as Guest</button>
    </div>


    {errorMsg && <p className="error">{errorMsg}</p>}
  </form>

  <p>Already Registered? <Link to="/login">Login Here</Link></p>
</div>

  );
};

export default SignupView;
